import {normalizeSpeech} from './audio-studio.mjs';
export function createAtlasReader(){let token=0,audio=null,utterance=null;const stop=()=>{token++;audio?.pause();audio=null;globalThis.speechSynthesis?.cancel();utterance=null;};
 async function read(guide,dialog){stop();const id=token,status=dialog.querySelector('#atlasVoiceStatus');document.querySelectorAll('video,audio').forEach(p=>p.pause());let manifest={};try{const r=await fetch('narration/manifest.json');if(r.ok)manifest=await r.json();}catch{}if(id!==token)return;
 if(manifest[guide.id]){audio=new Audio(manifest[guide.id]);audio.onended=()=>status.textContent='Narración terminada · voz generada por IA';audio.onerror=()=>status.textContent='No se pudo cargar la narración. El texto sigue disponible.';status.textContent='Narración de estudio · voz generada por IA';try{await audio.play();}catch{status.textContent='No se pudo iniciar el audio. Pulsa Escuchar para volver a intentarlo.';}return;}
 const synth=globalThis.speechSynthesis;if(!synth||!globalThis.SpeechSynthesisUtterance){status.textContent='Este navegador no ofrece voz de lectura. Puedes seguir la explicación en texto.';return;}let settings={};try{settings=JSON.parse(localStorage.getItem('circuitlab-audio-v19')||'{}')}catch{}const voices=synth.getVoices(),voice=voices.find(v=>v.voiceURI===settings.voice)||voices.find(v=>v.lang==='es-ES')||voices.find(v=>v.lang.startsWith('es'));const chunks=normalizeSpeech(guide.text).split(/(?<=[.!?])\s+/);let index=0;const next=()=>{if(id!==token)return;if(index===chunks.length){status.textContent='Lectura terminada · voz del dispositivo';return;}utterance=new SpeechSynthesisUtterance(chunks[index++]);utterance.lang='es-ES';utterance.voice=voice||null;utterance.rate=settings.speechRate||.95;utterance.volume=settings.volume??.85;utterance.onend=next;utterance.onerror=()=>{if(id===token)status.textContent='La voz del dispositivo no ha podido continuar.';};status.textContent=`Voz del dispositivo · ${index}/${chunks.length} · narración de estudio pendiente`;synth.speak(utterance);};next();}
 document.addEventListener('circuitlab:page',stop);return {read,stop};}
